view.template:
{% load view_tags %}

{# ############# #}
{# PROJECT TITLE #}
{# ############# #}
<h1>{% render_value 'project/title' %}</h1>

{# ################# #}
{# RESEARCH FIELD(S) #}
{# ################# #}
{% get_values 'project/research_field' as research_fields %}
<p>This software belongs to the research field{{ research_fields|pluralize }}: {% if research_fields|length == 1 %}{{ research_fields.0.value }}
  {% elif research_fields|length > 1 %}
  <ul>
  {% for rf in research_fields %}
    <li>{{ rf.value }}</li>
  {% endfor %}
  </ul>
  {% endif %}
</p>

{# ######################################### #}
{# INTENDED USE AND CONTRIBUTION TO RESEARCH #}
{# ######################################### #}
{% get_value 'project/research_question/title' as research_question_title %}
<p>Its intended use and its contribution to research:</p>
<p>{{ research_question_title.value|linebreaks }}</p>

{# ############## #}
{# CONTRIBUTOR(S) #}
{# ############## #}
{% get_set 'project/partner/id' as partners %}
<p>Contributor(s)
<ul>
{% for p in partners %}
  {% get_set_value p 'project/partner/orcid-id' as p_orcid_id %}
  {% get_set_value p 'project/partner/given-name' as p_given_name %}
  {% get_set_value p 'project/partner/family-name' as p_family_name %}
  {% get_values 'project/partner/affiliation' p.set_index as p_affiliations %}
  {% get_values 'project/partner/role' p.set_index as p_roles %}

  <li>{% if p_given_name and p_family_name %}{{ p_given_name.value }} {{ p_family_name.value }}{% else %}{{ p.value }}{% endif %}{% if p_orcid_id.value %} ({{ p_orcid_id.value }}){% endif %}{% if p_affiliations %}, {% for a in p_affiliations %}{% for r in p_roles %}{% if r.set_index == a.set_index %}{{ r.value }} at {% endif %}{% endfor %}{{ a.value }}{% if not forloop.last %} & {% endif %}{% endfor %}{% else %}{% if p_roles %}, {% for r in p_roles %}{{ r.value }}{% if not forloop.last %} & {% endif %}{% endfor %}{% endif %}{% endif %}</li>

{% endfor %}
</ul>
</p>

{# ########## #}
{# LICENSE(S) #}
{# ########## #}
{% get_values 'smp/software-license' as software_licenses %}
<p>Software license{{ software_licenses|pluralize }}: {% if software_licenses|length == 1 %}{% if software_licenses.0.text %}{{ software_licenses.0.text }}{% else %}{{ software_licenses.0.option_text }}{% endif %}
{% elif software_licenses|length > 1 %}
<ul>
  {% for sl in software_licenses %}
    <li>{% if sl.text %}{{ sl.text }}{% else %}{{ sl.option_text }}{% endif %}</li>
  {% endfor %}
</ul>
{% endif %}
</p>

{# ##### #}
{# SETUP #}
{# ##### #}
<h3>Setup</h3>
<b>[ToDo]</b>

{# ##### #}
{# USAGE #}
{# ##### #}
<h3>Usage</h3>
<b>[ToDo]</b>
